recipes.command:
mkdir -p apps/scraper && cd apps/scraper && npm init -y && npm install axios cheerio && cat << 'SEOF' > index.js
import axios from 'axios';
import * as cheerio from 'cheerio';
const { data } = await axios.get('https://news.ycombinator.com/');
const $ = cheerio.load(data);
$('.titleline > a').slice(0, 5).each((i, el) => console.log(`${i + 1}. ${$(el).text()}`));
SEOF
node index.js
